      { sku: 'DES-HOUR', qty: 2, discountPercent: 20 },
      { sku: 'DEV-HOUR', qty: 1, discountPercent: 15 },
    ],
  });
  const r2 = removeLine(r.value, 'DES-HOUR');
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(r2.value.lines[0].discountPercent, 15);
});

test('issueInvoice assigns a number and changes status to issued', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const r2 = issueInvoice(r.value, []);
  assert.equal(r2.ok, true);
  assert.equal(r2.value.number, 'INV-2026-0001');
  assert.equal(r2.value.status, 'issued');
  assert.equal(r2.value.customerId, 'C-001');
  assert.equal(r2.value.issueDate, '2026-10-07');
});

test('issueInvoice uses existing numbers to find next', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const r2 = issueInvoice(r.value, ['INV-2026-0001', 'INV-2026-0003']);
  assert.equal(r2.value.number, 'INV-2026-0004');
});

test('issueInvoice reports NOT_DRAFT for non-draft invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const nonDraft = { ...r.value, status: 'issued' };
  assert.deepEqual(issueInvoice(nonDraft, []), { ok: false, error: 'NOT_DRAFT' });
});

test('issueInvoice does not mutate the original invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  issueInvoice(r.value, []);
  assert.equal(r.value.status, 'draft');
  assert.equal(r.value.number, undefined);
});
